+ARGON2_PUBLIC void
+argon2_adaptive_current_params(const argon2_adaptive_controller *controller,
+                               argon2_adaptive_params *params) {
+    if (params == NULL) {
+        return;
+    }
+    memset(params, 0, sizeof(*params));
+    if (controller == NULL) {
+        return;
