+static void run_concurrency_round(argon2_adaptive_controller *controller,
+                                  int worker_count,
+                                  argon2_adaptive_tier expected_tier) {
+    pthread_t threads[MAX_ROUND_WORKERS];
+    worker_arg args[MAX_ROUND_WORKERS];
